-- Explicações por artigo — Lei da Identificação Criminal (Lei nº 12.037, de 2009). Texto-base: dispositivos oficiais já cadastrados em legal_course_units.

-- Entram como 'under_review': só administradores veem até a publicação (update ... set status = 'published').

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O civilmente identificado não será submetido a identificação criminal, salvo nos casos previstos nesta Lei.', '["Regra: quem tem identificação civil não passa por identificação criminal.","Exceções: casos da própria Lei (art. 3º)."]'::jsonb, '["Base constitucional: art. 5º, LVIII, da Constituição.","A exceção é a identificação criminal."]'::jsonb, 'Quem apresenta carteira de identidade válida, em regra, não é fotografado nem tem as digitais colhidas para fins criminais.', '["Assertiva que torna a identificação criminal obrigatória para todo indiciado erra: a regra é a identificação civil."]'::jsonb, '[{"termo":"Identificação criminal","significado":"Coleta de dados datiloscópicos, fotográficos e, em certos casos, genéticos."}]'::jsonb, '["Art. 3º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'identificacao-criminal' and u.unit_key = 'art-1'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A identificação civil é atestada por qualquer dos seguintes documentos: carteira de identidade, carteira de trabalho, carteira profissional, passaporte, carteira de identificação funcional e outro documento público que permita a identificação do indiciado. Para as finalidades desta Lei, equiparam-se aos documentos de identificação civis os documentos de identificação militares.', '["Documentos que atestam a identificação civil.","Rol com cláusula aberta: outro documento público.","Documentos militares são equiparados."]'::jsonb, '["Documento militar vale como civil para esta Lei."]'::jsonb, 'A carteira de trabalho comprova a identificação civil do indiciado.', '["Assertiva que exclui a carteira funcional do rol erra: ela está prevista."]'::jsonb, '[]'::jsonb, '["Art. 1º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'identificacao-criminal' and u.unit_key = 'art-2'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Embora apresentado documento de identificação, poderá ocorrer identificação criminal quando o documento apresentar rasura ou indício de falsificação; for insuficiente para identificar cabalmente o indiciado; houver documentos distintos com informações conflitantes; a medida for essencial às investigações, segundo despacho do juiz, de ofício ou por representação da autoridade policial, do Ministério Público ou da defesa; constarem registros policiais de outros nomes ou qualificações; o estado de conservação ou a distância temporal ou de localidade da expedição impossibilitarem a identificação; ou houver recebimento da denúncia por crime praticado com grave violência contra a pessoa, crime contra a liberdade sexual ou sexual contra vulnerável, crimes contra criança ou adolescente previstos nos arts. 240, 241, 241-A, 241-B e 241-C do ECA, ou crime do art. 2º da Lei de Organizações Criminosas quando a organização utilizar armas de fogo. As cópias dos documentos apresentados serão juntadas aos autos.', '["Rasura ou indício de falsificação.","Documento insuficiente ou conflitante.","Essencial às investigações, por despacho judicial.","Registros de outros nomes.","Documento antigo ou de difícil verificação.","Recebimento da denúncia por certos crimes graves (inciso VII)."]'::jsonb, '["ATUALIZAÇÃO: inciso VII incluído pela Lei nº 13.964, de 2019 (Pacote Anticrime).","A decisão judicial do inciso IV pode ser de ofício ou por provocação."]'::jsonb, 'Quem apresenta documento com sinais de falsificação pode ser submetido à identificação criminal.', '["Assertiva que dispensa decisão judicial no caso do inciso IV erra: exige despacho da autoridade judiciária."]'::jsonb, '[]'::jsonb, '["Art. 5º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'identificacao-criminal' and u.unit_key = 'art-3'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Quando houver necessidade de identificação criminal, a autoridade encarregada tomará as providências necessárias para evitar o constrangimento do identificado.', '["Dever de evitar constrangimento ao identificado."]'::jsonb, '["Proteção da dignidade durante a identificação."]'::jsonb, 'A coleta de impressões é feita de forma reservada, sem exposição pública do indiciado.', '["Assertiva que autoriza a exposição do identificado ao público erra: a autoridade deve evitar constrangimento."]'::jsonb, '[]'::jsonb, '["Art. 3º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'identificacao-criminal' and u.unit_key = 'art-4'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A identificação criminal incluirá o processo datiloscópico e o fotográfico, que serão juntados aos autos da comunicação da prisão em flagrante, do inquérito policial ou de outra forma de investigação. Nas hipóteses dos incisos IV e VII do art. 3º, incluirá também a coleta de material biológico para a obtenção do perfil genético. Nos casos de prisão em flagrante pelos crimes do inciso VII do art. 3º, a identificação criminal também incluirá a coleta de material biológico para o perfil genético.', '["Processo datiloscópico e fotográfico.","Juntada aos autos da prisão em flagrante ou do inquérito.","Perfil genético nos incisos IV e VII do art. 3º.","Perfil genético também na prisão em flagrante pelos crimes do inciso VII."]'::jsonb, '["ATUALIZAÇÃO: §§1º e 2º incluídos pela Lei nº 13.964, de 2019.","O perfil genético não é regra geral: depende das hipóteses legais."]'::jsonb, 'Em flagrante de crime sexual contra vulnerável, a identificação inclui coleta de material genético.', '["Assertiva que torna a coleta genética automática em toda identificação criminal erra: só nas hipóteses legais."]'::jsonb, '[{"termo":"Datiloscópico","significado":"Relativo às impressões digitais."}]'::jsonb, '["Art. 5º-A","Art. 7º-A"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'identificacao-criminal' and u.unit_key = 'art-5'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os dados relacionados à coleta do perfil genético deverão ser armazenados em banco de dados de perfis genéticos, gerenciado por unidade oficial de perícia criminal. As informações genéticas não poderão revelar traços somáticos ou comportamentais das pessoas, exceto determinação genética de gênero. Os dados terão caráter sigiloso, e quem permitir ou promover seu uso para fins diversos responderá civil, penal e administrativamente. As informações obtidas a partir da coincidência de perfis genéticos serão consignadas em laudo pericial firmado por perito oficial habilitado.', '["Banco de perfis genéticos gerido por unidade oficial de perícia criminal.","Vedado revelar traços somáticos ou comportamentais, exceto o gênero.","Dados sigilosos.","Coincidência registrada em laudo de perito oficial."]'::jsonb, '["ATUALIZAÇÃO: incluído pela Lei nº 12.654, de 2012, com alterações posteriores.","Uso indevido gera responsabilização civil, penal e administrativa."]'::jsonb, 'A coincidência entre vestígio da cena do crime e um perfil do banco gera laudo pericial.', '["Assertiva que permite revelar traços comportamentais do investigado erra: é vedado."]'::jsonb, '[]'::jsonb, '["Art. 7º-A"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'identificacao-criminal' and u.unit_key = 'art-5-a'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'É vedado mencionar a identificação criminal do indiciado em atestados de antecedentes ou em informações não destinadas ao juízo criminal, antes do trânsito em julgado da sentença condenatória.', '["Vedada a menção da identificação criminal em atestados de antecedentes.","Vale antes do trânsito em julgado da condenação."]'::jsonb, '["Proteção da presunção de inocência."]'::jsonb, 'O atestado de antecedentes entregue ao empregador não pode citar a identificação criminal de indiciado.', '["Assertiva que autoriza a menção em atestados antes do trânsito em julgado erra."]'::jsonb, '[]'::jsonb, '["Art. 7º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'identificacao-criminal' and u.unit_key = 'art-6'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'No caso de não oferecimento da denúncia, ou sua rejeição, ou absolvição, é facultado ao indiciado ou ao réu, após o arquivamento definitivo do inquérito ou o trânsito em julgado da sentença, requerer a retirada da identificação fotográfica do inquérito ou processo, desde que apresente provas de sua identificação civil.', '["Direito de pedir a retirada da fotografia.","Hipóteses: sem denúncia, rejeição ou absolvição.","Após arquivamento definitivo ou trânsito em julgado.","Exige prova da identificação civil."]'::jsonb, '["A retirada alcança a identificação FOTOGRÁFICA."]'::jsonb, 'O absolvido pede a retirada de sua foto do processo, comprovando sua identidade civil.', '["Assertiva que permite a retirada da foto antes do arquivamento definitivo erra."]'::jsonb, '[]'::jsonb, '["Art. 6º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'identificacao-criminal' and u.unit_key = 'art-7'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A exclusão dos perfis genéticos dos bancos de dados ocorrerá no caso de absolvição do acusado ou, no caso de condenação, mediante requerimento, após decorridos 20 anos do cumprimento da pena.', '["Absolvição: exclusão do perfil genético.","Condenação: exclusão a requerimento, após vinte anos do cumprimento da pena."]'::jsonb, '["ATUALIZAÇÃO: incluído pela Lei nº 12.654, de 2012.","Prazo de 20 anos para o condenado."]'::jsonb, 'O condenado pode pedir a exclusão do perfil depois de vinte anos do cumprimento da pena.', '["Assertiva que fixa em 5 anos o prazo para o condenado pedir a exclusão erra: são 20 anos."]'::jsonb, '[]'::jsonb, '["Art. 5º-A"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'identificacao-criminal' and u.unit_key = 'art-7-a'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A identificação do perfil genético será armazenada em banco de dados sigiloso, conforme regulamento a ser expedido pelo Poder Executivo.', '["Armazenamento em banco de dados sigiloso.","Regulamento do Poder Executivo."]'::jsonb, '["ATUALIZAÇÃO: incluído pela Lei nº 12.654, de 2012."]'::jsonb, 'O perfil genético fica em banco sigiloso regulamentado pelo Executivo.', '["Assertiva que torna público o banco de perfis genéticos erra: é sigiloso."]'::jsonb, '[]'::jsonb, '["Art. 5º-A"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'identificacao-criminal' and u.unit_key = 'art-7-b'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Fica autorizada a criação, no Ministério da Justiça e Segurança Pública, do Banco Nacional Multibiométrico e de Impressões Digitais, para armazenar dados de registros biométricos, de impressões digitais e, quando possível, de íris, face e voz, para subsidiar investigações criminais federais, estaduais ou distritais. É integrado pelos registros colhidos em investigações ou na identificação criminal, e podem ser colhidos registros de presos provisórios ou definitivos. Outros bancos podem integrar-se ou interoperar mediante acordo ou convênio. Os dados são sigilosos, é vedada a comercialização da base e as coincidências constam de laudo pericial. A autoridade policial e o Ministério Público podem requerer ao juiz o acesso no caso de inquérito ou ação penal instaurados.', '["Banco no Ministério da Justiça e Segurança Pública.","Armazena biometria, digitais e, quando possível, íris, face e voz.","Integração por acordo ou convênio.","Dados sigilosos, sem comercialização.","Acesso por requerimento ao juiz."]'::jsonb, '["ATUALIZAÇÃO: incluído pela Lei nº 13.964, de 2019 (Pacote Anticrime).","Integração com bancos civis limitada às digitais e à identificação."]'::jsonb, 'A polícia pede ao juiz acesso ao banco para identificar um suspeito em inquérito.', '["Assertiva que permite a venda da base do banco biométrico erra: é vedada a comercialização."]'::jsonb, '[]'::jsonb, '["Art. 5º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'identificacao-criminal' and u.unit_key = 'art-7-c'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
