insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Revoga-se a Lei nº 10.054, de 7 de dezembro de 2000, que tratava anteriormente da identificação criminal.', '["Revoga a lei anterior sobre identificação criminal."]'::jsonb, '["Dispositivo histórico."]'::jsonb, 'A nova lei substituiu a lei de dois mil.', '["Assertiva que mantém em vigor a lei anterior erra: foi revogada."]'::jsonb, '[]'::jsonb, '["Art. 8º"]'::jsonb, 'under_review', 'claude'
